INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "王檀率关西梁军袭击晋阳并急攻城垒。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：匡国节度使王檀密疏请发关西兵袭晋阳，帝从之，发河中、陕、同华诸镇兵合三万，出阴地关，奄至晋阳城下，昼夜急攻。；核对说明：主书作三万，旧五代史卷八另列谢彦章、王彦章，卷二十八记五万；分歧并列。", "status": "draft", "id": "2c6d6ae3-dc1f-50f9-b7a2-08ec47815638", "subject_id": "20d14eab-5601-50df-9aa9-4fef98c531f7", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "916年二月至三月间；主书本段未明日", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：匡国节度使王檀密疏请发关西兵袭晋阳，帝从之，发河中、陕、同华诸镇兵合三万，出阴地关，奄至晋阳城下，昼夜急攻。；核对说明：按主书段落次序；干支未换算公历日。", "status": "draft", "id": "467ebc9a-cba1-5366-a9df-47c52239560f", "subject_id": "20d14eab-5601-50df-9aa9-4fef98c531f7", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王檀：上疏请求袭晋阳并领军急攻的梁将。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：匡国节度使王檀密疏请发关西兵袭晋阳，帝从之，发河中、陕、同华诸镇兵合三万，出阴地关，奄至晋阳城下，昼夜急攻。；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形。", "status": "draft", "id": "5486fe1c-0b0d-5e21-bb40-7196cd434ef2", "subject_id": "c87cad89-b794-5ba5-8151-354817e56a5d", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王檀：上疏请求袭晋阳并领军急攻的梁将。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：匡国节度使王檀密疏请发关西兵袭晋阳，帝从之，发河中、陕、同华诸镇兵合三万，出阴地关，奄至晋阳城下，昼夜急攻。；核对说明：参与身份依据本句；称谓按既有主体匹配。", "status": "draft", "id": "c230bac2-e8c3-53d4-9988-cd0343168a86", "subject_id": "886f45d8-d1e2-553b-8eef-e54e9d83b882", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱友贞：批准王檀所请并发兵的后梁皇帝。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：匡国节度使王檀密疏请发关西兵袭晋阳，帝从之，发河中、陕、同华诸镇兵合三万，出阴地关，奄至晋阳城下，昼夜急攻。；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形。", "status": "draft", "id": "882c3db4-a670-5bd3-bb4b-5d7e1461ab7e", "subject_id": "592627e4-8841-5cca-a79b-782c37765037", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱友贞：批准王檀所请并发兵的后梁皇帝。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：匡国节度使王檀密疏请发关西兵袭晋阳，帝从之，发河中、陕、同华诸镇兵合三万，出阴地关，奄至晋阳城下，昼夜急攻。；核对说明：参与身份依据本句；称谓按既有主体匹配。", "status": "draft", "id": "0aaa202d-3318-5a59-90c5-a82499b5d1af", "subject_id": "f57372a4-d454-5a23-9d2f-dcdb873c4a7f", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷八记二月王檀与谢彦章、王彦章自阴地关攻晋阳。", "citation": "《旧五代史》卷八，段落 jiu-wudaishi-205deb4a7860-p000383；EPUB电子本，纸本及异文待核", "note": "原文：是月，命許州節度使王檀、河陽節度使謝彥章、汝州防禦使王彥章率師自陰地關抵晉陽，急攻其壘，不克而還。；核对说明：本纪年条作二月并增加两将；主书此段未逐名列出，未把二人加入主书参与边。", "status": "draft", "id": "f4f49053-a3d4-5069-a964-7295a1f4e85d", "subject_id": "20d14eab-5601-50df-9aa9-4fef98c531f7", "source_id": "68bbc60e-df8c-5167-a0ce-982f1095b272"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷二十八记王檀所率为五万，与主书三万不同。", "citation": "《旧五代史》卷二十八，段落 jiu-wudaishi-205deb4a7860-p000930；EPUB电子本，纸本及异文待核", "note": "原文：是月，梁主遣別將王檀率兵五萬，自陰地關趨晉陽，急攻其城；核对说明：该段在三月战后叙王檀；兵数及编次与主书、旧书卷八有异，不能混成一个确数。", "status": "draft", "id": "d1ec3506-8e49-5bce-aaa3-a1be58fe284a", "subject_id": "20d14eab-5601-50df-9aa9-4fef98c531f7", "source_id": "e3944459-644a-522d-85ad-6126e4f824b4"}, {"subject_table": "event", "field_path": "description", "claim_text": "安金全率子弟、退将夜出晋阳北门击退梁军。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：承业即与之。金全帅其子弟及退将之家得数百人，夜出北门，击梁兵于羊马城内。梁兵大惊，引却。；核对说明：张承业授甲见同段上文，数百人为主书记数，不以新五代史百余人改写。", "status": "draft", "id": "cb7a7321-b5f9-59d0-9f13-32c5e3e44b8c", "subject_id": "8388e403-9ac3-51e5-aff1-aff8f1a6cfdd", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "916年晋阳受攻夜间；确日未载", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：承业即与之。金全帅其子弟及退将之家得数百人，夜出北门，击梁兵于羊马城内。梁兵大惊，引却。；核对说明：按主书段落次序；干支未换算公历日。", "status": "draft", "id": "5406129a-20b7-58a9-aa11-73a8b8a62716", "subject_id": "8388e403-9ac3-51e5-aff1-aff8f1a6cfdd", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记安金全：率数百人出北门击梁军的退将。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：承业即与之。金全帅其子弟及退将之家得数百人，夜出北门，击梁兵于羊马城内。梁兵大惊，引却。；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形。", "status": "draft", "id": "53b06943-ccb7-5265-b444-2b30c5d4a81c", "subject_id": "b52eca39-fd61-599b-8624-160fbb4ec282", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "安金全：率数百人出北门击梁军的退将。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：承业即与之。金全帅其子弟及退将之家得数百人，夜出北门，击梁兵于羊马城内。梁兵大惊，引却。；核对说明：参与身份依据本句；称谓按既有主体匹配。", "status": "draft", "id": "4a27067a-6534-57c3-8d79-046fd44d584a", "subject_id": "bdb22a63-9a64-54e7-bb4a-153bb7b50179", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记张承业：将库甲授安金全并组织守城的监军。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：承业即与之。金全帅其子弟及退将之家得数百人，夜出北门，击梁兵于羊马城内。梁兵大惊，引却。；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形。", "status": "draft", "id": "95a83536-de25-5b94-8120-e3b412fc6e39", "subject_id": "abe0cfa0-d9c2-52c4-8905-46bdeb978c83", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张承业：将库甲授安金全并组织守城的监军。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：承业即与之。金全帅其子弟及退将之家得数百人，夜出北门，击梁兵于羊马城内。梁兵大惊，引却。；核对说明：参与身份依据本句；称谓按既有主体匹配。", "status": "draft", "id": "5c0cdc4d-c45a-51f9-9a53-47a0760da142", "subject_id": "8592010a-753a-5569-addb-56058edffefc", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》安金全传也记数百人夜出北门击退梁军。", "citation": "《旧五代史》卷六十一，段落 jiu-wudaishi-205deb4a7860-p001607；EPUB电子本，纸本及异文待核", "note": "原文：得數百人。夜出北門，擊賊於羊馬城內，梁人驚潰，由是退卻。；核对说明：旧书列传与主书人数和行动大体相合；原文保留繁体。", "status": "draft", "id": "ecaf85b1-ed46-5cd7-97d5-537b41aa782a", "subject_id": "8388e403-9ac3-51e5-aff1-aff8f1a6cfdd", "source_id": "0122fa41-be97-51d7-8bb7-d0b78089e52f"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》安金全传称所率百余人，与主书数百人不同。", "citation": "《新五代史》卷二十五，段落 xin-wudaishi-b08f244b9241-p000905；EPUB电子本，纸本及异文待核", "note": "原文：召率子弟及故將吏得百餘人，夜出北門，擊檀於羊馬城中；核对说明：人数差异保留，不把百余与数百累加。", "status": "draft", "id": "73a6ae9d-1846-534d-8372-7ffe81bb6a69", "subject_id": "8388e403-9ac3-51e5-aff1-aff8f1a6cfdd", "source_id": "bbc70dbb-b747-5f1f-82db-f338e471c3fd"}, {"subject_table": "event", "field_path": "description", "claim_text": "石君立率骑兵自上党救晋阳并突破汾河桥。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：昭义节度使李嗣昭闻晋阳有寇，遣牙将石君立将五百骑救之。君立朝发上党，夕至晋阳。梁兵扼汾河桥，君立击破之；核对说明：主书与旧五代史石君立传一致记石君立五百骑；旧书卷二十八异作石嘉才三百骑。", "status": "draft", "id": "94623a09-dfbd-565c-b71e-e5cfd26ba7b0", "subject_id": "a99ec5a1-26d3-51fb-a690-4329c034f40e", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "916年晋阳受攻期间；确日未载", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：昭义节度使李嗣昭闻晋阳有寇，遣牙将石君立将五百骑救之。君立朝发上党，夕至晋阳。梁兵扼汾河桥，君立击破之；核对说明：按主书段落次序；干支未换算公历日。", "status": "draft", "id": "08cff096-0953-5981-b641-358e03d497cb", "subject_id": "a99ec5a1-26d3-51fb-a690-4329c034f40e", "source_id": "5f7c9671-868f-5c7d-b86d-8871710fafa0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李嗣昭：遣牙将救援晋阳的昭义节度使。", "citation": "卷269·贞明二年（916）·zztj-v269-y0916-p005·原文件第69行", "note": "原文：昭义节度使李嗣昭闻晋阳有寇，遣牙将石君立将五百骑救之。君立朝发上党，夕至晋阳。梁兵扼汾河桥，君立击破之；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形